#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> graph(N + 1);
    for (int i = 1; i <= N; ++i) {
        int M;
        cin >> M;
        while (M--) {
            int x;
            cin >> x;
            graph[i].push_back(x);
        }
    }

    vector<int> team(N + 1, -1);
    queue<int> q;
    team[1] = 0;
    q.push(1);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : graph[u]) {
            if (team[v] == -1) {
                team[v] = team[u] ^ 1;
                q.push(v);
            }
        }
    }

    for (int t = 0; t < 2; ++t) {
        bool first = true;
        for (int i = 1; i <= N; ++i) {
            if (team[i] == t) {
                if (!first) cout << ' ';
                cout << i;
                first = false;
            }
        }
        cout << '\n';
    }

    return 0;
}
